SourceText:
 minister_grand_chancellor_action_breakdown: "#indent_newline:4 #weak Этот министр может, например:
$BULLET$прибегать к [Concept('decision', 'решению')|E] «[GetDecision('favored_movement_consults_heaven_decision').GetName|V]»;
$BULLET$приглашать любых [Concept('courtier', 'придворных')|E] при помощи [Concept('decision', 'решения')|E] «[GetDecision('tgp_minister_recruit_courtiers_decision').GetName|V]»;
$BULLET$использовать особые вариации [Concept('interaction', 'взаимодействия')|E] #V «$influence_meritorious_career_interaction$»#! с меньшими затратами;
$BULLET$начать [Concept('great_project', 'грандиозный проект')|E] «[GetGreatProjectType('minister_compel_religious_uniformity').GetName|V]».#!#!"

 minister_grand_chancellor_action_breakdown: "#indent_newline:4 #weak Этот министр может, например:
$BULLET$прибегать к [Concept('decision', 'решению')|E] «[GetDecision('favored_movement_consults_heaven_decision').GetName|V]»;
$BULLET$приглашать любых [Concept('courtier', 'придворных')|E] при помощи [Concept('decision', 'решения')|E] «[GetDecision('tgp_minister_recruit_courtiers_decision').GetName|V]»;
$BULLET$использовать особые вариации [Concept('interaction', 'взаимодействия')|E] #V «$influence_meritorious_career_interaction$»#! с меньшими затратами;
$BULLET$начать [Concept('great_project', 'грандиозный проект')|E] «[GetGreatProjectType('minister_compel_religious_uniformity').GetName|V]».#!#!"

 minister_grand_chancellor_action_breakdown: "#indent_newline:4 #weak Ten minister może na przykład:
$BULLET$podjąć [Concept('decision', 'decyzję')|E] „[GetDecision('favored_movement_consults_heaven_decision').GetName|V]”;
$BULLET$zaprosić dowolnego [Concept('courtier', 'dworzanina')|E] za pomocą [Concept('decision', 'decyzji')|E] „[GetDecision('tgp_minister_recruit_courtiers_decision').GetName|V]”;
$BULLET$uzyskać dostęp do specjalnych opcji [Concept('interaction', 'interakcji')|E] #V „$influence_meritorious_career_interaction$”#!, ponosząc niższe koszty;
$BULLET$rozpocząć [great_project|El] „[GetGreatProjectType('minister_compel_religious_uniformity').GetName|V]”.#!#!"

 minister_of_personnel_action_breakdown: "#indent_newline:4 #weak Ten minister może na przykład:
$BULLET$użyć [Concept('interaction', 'interakcji')|E] #V „$force_governor_removal_interaction$”#!, aby zwolnić [Concept('governors', 'gubernatorów')|E] niezależnie od ustanowionego [Concept('law', 'prawa')|E] „[GetLawGroup('celestial_retirement_law').GetName]”;
$BULLET$zaprosić dowolnego [Concept('courtier', 'dworzanina')|E], podejmując [Concept('decision', 'decyzję')|E] „[GetDecision('tgp_minister_recruit_courtiers_decision').GetName|V]”;
$BULLET$wymusić akceptację [Concept('interactions', 'interakcji')|E] #V „$offer_courtier_interaction$”#! oraz #V „$demand_courtier_interaction$”#!;
$BULLET$uzyskać dostąp do specjalnych opcji [Concept('interaction', 'interakcji')|E] #V „$influence_meritorious_career_interaction$”#!, ponosząc niższe koszty.#!#!"
